<script setup lang="ts">
import { t } from '../i18n'
import { computed, ref } from 'vue'
import type { SearchOperatorSpace, SearchRecipeEntry } from '../types/search'

const props = defineProps<{ entries: SearchRecipeEntry[]; space?: SearchOperatorSpace }>()
const mode = ref('methods'), query = ref(''), selected = ref('')
const entries = computed(() => props.entries.filter(e => `${e.title} ${e.id}`.toLowerCase().includes(query.value.toLowerCase())))
const entry = computed(() => entries.value.find(e => e.id === selected.value) ?? entries.value[0])
const origin = (value: string) => (({ get basic() { return t('Baseline method') }, get literature() { return t('Literature method') }, get literature_adaptation() { return t('Adapted literature method') } } as Record<string, string>)[value] ?? value)
const operator = (id: string) => props.space?.operators.find(o => o.id === id)?.title ?? id
const value = (v: unknown) => typeof v === 'object' ? JSON.stringify(v) : String(v)
const stage = (v: string) => (({ get continuous() { return t('Continuous signal') }, get epochs() { return t('Epochs') }, get either() { return t('Continuous signal / epochs') }, get same() { return t('Preserve data representation') } } as Record<string, string>)[v] ?? v)
const editLabel = (v: string) => (({ get set_parameter() { return t('Adjust parameters') }, get swap_adjacent() { return t('Swap adjacent steps') }, get insert_operator() { return t('Insert operator') }, get remove_operator() { return t('Remove operator') }, get set_adaptation() { return t('Adjust subject adaptation') } } as Record<string, string>)[v] ?? v)
const adaptation = (v: string) => (({ get none() { return t('Preserve physical amplitude') }, get subject_scale() { return t('Per-subject scaling') }, get euclidean_alignment() { return t('Unlabeled per-subject Euclidean alignment') }, get conditional_alignment() { return t('Diagnosis-conditioned per-subject alignment') } } as Record<string, string>)[v] ?? v)
const webLink = (v: string) => /^https?:\/\//i.test(v)
</script>

<template>
  <section class="method-explorer" :aria-label="t('Method and operator search space')">
    <div class="explorer-nav"><button v-for="(label, key) in { methods: t('Methods and candidates'), operators: t('Operators and parameters'), priors: t('Order and scientific priors') }" :key="key" :aria-pressed="mode === key" @click="mode = key">{{ label }}</button></div>
    <div v-if="mode === 'methods'" class="method-layout">
      <aside>
        <label class="search-label">{{ t('Find a method') }}<input v-model="query" type="search" :placeholder="t('Method name or ID')" /></label>
        <nav :aria-label="t('Candidate recipes')"><button v-for="item in entries" :key="item.id" :aria-pressed="entry?.id === item.id" @click="selected = item.id"><strong>{{ item.title }}</strong><small>{{ t('{0} · {1} operators', { 0: item.parent_id ? t('Search candidate') : origin(item.origin), 1: item.recipe.nodes.length + (item.recipe.adaptation.adaptation === 'none' ? 0 : 1) }) }}</small></button></nav>
      </aside>
      <article v-if="entry" class="recipe-detail">
        <header><span class="kicker">{{ origin(entry.origin) }}</span><h3>{{ entry.title }}</h3><p class="muted">{{ entry.id }}</p></header>
        <p v-if="entry.parent_id" class="lineage">{{ t('Parent method:') }}<button @click="selected = entry.parent_id; query = ''">{{ props.entries.find(e => e.id === entry?.parent_id)?.title ?? entry.parent_id }}</button></p>
        <ol class="operator-flow"><li v-for="(node, index) in entry.recipe.nodes" :key="node.id"><span class="step-number">{{ index + 1 }}</span><div><strong>{{ operator(node.operator) }}</strong><dl v-if="Object.keys(node.parameters).length"><template v-for="(v, name) in node.parameters" :key="name"><dt>{{ name }}</dt><dd>{{ value(v) }}</dd></template></dl><small v-else class="muted">{{ t('Uses the shared data and output contract') }}</small></div></li></ol>
        <div class="adaptation"><strong>{{ t('Subject representation') }}</strong><span>{{ adaptation(entry.recipe.adaptation.adaptation) }}<template v-if="entry.recipe.adaptation.adaptation === 'conditional_alignment'">{{ t('· Threshold {0}', { 0: entry.recipe.adaptation.alignment_threshold }) }}</template></span></div>
        <section v-if="entry.edits.length"><h4>{{ t('Search edits') }}</h4><ul><li v-for="(edit, i) in entry.edits" :key="i"><strong>{{ editLabel(edit.action) }}</strong><span class="muted">{{ Object.entries(edit).filter(([k]) => k !== 'action').map(([k,v]) => `${k}: ${value(v)}`).join(' · ') }}</span></li></ul></section>
        <section v-if="entry.deviations.length"><h4>{{ t('Applicability and method adaptations') }}</h4><ul><li v-for="note in entry.deviations" :key="note">{{ note }}</li></ul></section>
        <section v-if="Object.keys(entry.prior_challenges).length"><h4>{{ t('Prior challenges requiring experimental evidence') }}</h4><p v-for="(reason, key) in entry.prior_challenges" :key="key"><strong>{{ key }}</strong> {{ reason }}</p></section>
        <section v-if="entry.evidence_ids.length"><h4>{{ t('Method references') }}</h4><p v-for="key in entry.evidence_ids" :key="key"><template v-if="space?.evidence[key]"><a v-if="webLink(space.evidence[key].source_url)" :href="space.evidence[key].source_url" target="_blank" rel="noopener noreferrer">{{ space.evidence[key].locator }} ↗</a><span v-else>{{ space.evidence[key].locator }}</span><small class="muted">{{ space.evidence[key].text }}</small></template></p></section>
      </article>
      <p v-else class="empty">{{ t('No matching recipes.') }}</p>
    </div>
    <div v-else-if="mode === 'operators'" class="contract-list"><article v-for="op in space?.operators ?? []" :key="op.id"><header><h3>{{ op.title }}</h3><span class="pill">{{ op.required ? t('Required step') : t('Optional operator') }}</span></header><p class="muted">{{ stage(op.input_stage) }} → {{ stage(op.output_stage) }}</p><p v-if="op.requires.length">{{ t('Prerequisites: {0}', { 0: op.requires.join('、') }) }}</p><dl class="domains"><template v-for="(domain, key) in op.domains" :key="key"><dt>{{ key }}</dt><dd><strong>{{ domain.kind === 'choice' ? domain.choices?.map(value).join(' / ') : `${domain.minimum}–${domain.maximum} ${domain.unit}` }}</strong><small>{{ domain.rationale }} · {{ domain.origin === 'literature' ? t('Literature evidence') : t('Mathematical, implementation, or engineering bounds') }}</small></dd></template></dl><p v-if="op.input_highpass" class="muted">{{ t('Input spectrum requirements: {0}', { 0: op.input_highpass.rationale }) }}</p><p v-for="rule in op.separations ?? []" :key="rule.upper_parameter" class="muted">{{ rule.upper_parameter }} − {{ rule.lower_parameter }} ≥ {{ rule.minimum }}：{{ rule.rationale }}</p></article></div>
    <div v-else class="contract-list"><p class="muted">{{ t('Hard constraints ensure executable recipes. Soft priors may be challenged with a recorded rationale and measurements. Each rule applies only under its stated conditions.') }}</p><article v-for="prior in space?.priors ?? []" :key="prior.id"><header><h3>{{ prior.id }}</h3><span class="pill" :class="prior.strength">{{ prior.strength === 'hard' ? t('Hard constraints') : t('Challengeable priors') }}</span></header><p>{{ prior.rationale }}</p><small class="muted">{{ t('Applicable conditions: {0}', { 0: prior.condition }) }}</small><p v-for="key in prior.evidence_ids" :key="key"><a v-if="space?.evidence[key] && webLink(space.evidence[key].source_url)" :href="space.evidence[key].source_url" target="_blank" rel="noopener noreferrer">{{ space.evidence[key].locator }} ↗</a></p></article></div>
  </section>
</template>

<style scoped>
.method-explorer{color:#294638;font-size:13px}.explorer-nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}button{font:inherit;cursor:pointer;color:inherit;background:white;border:1px solid #d9e4dc;border-radius:7px;padding:8px 12px}button[aria-pressed=true]{background:#edf5ef;border-color:#83a990}.method-layout{display:grid;grid-template-columns:240px minmax(0,1fr);border:1px solid #e0e8e2;border-radius:10px;overflow:hidden;min-height:350px}.method-layout aside{border-right:1px solid #e0e8e2;padding:14px;background:#f9fbf9}.search-label{display:grid;gap:7px;font-size:12px;color:#728779}input{border:1px solid #d9e4dc;border-radius:6px;padding:9px;min-width:0;width:100%;box-sizing:border-box}nav{display:grid;gap:7px;max-height:54vh;overflow:auto;margin-top:13px}nav button{text-align:left;overflow-wrap:anywhere}nav small{display:block;margin-top:5px;color:#7b8b80}.recipe-detail{padding:24px;max-height:65vh;overflow:auto;min-width:0}.kicker{font-size:10px;letter-spacing:.08em;color:#728779}h3{font-size:17px;margin:6px 0}h4{font-size:13px;margin:20px 0 10px}.muted{color:#7c8c81;font-size:12px;overflow-wrap:anywhere}.lineage{padding:10px 0;border-bottom:1px solid #e7eee8}.lineage button{border:0;padding:0;color:#37765a;text-decoration:underline}.operator-flow{list-style:none;padding:0;margin:24px 0;display:grid;gap:20px}.operator-flow li{display:flex;gap:14px;position:relative}.step-number{border:1px solid #caddcf;background:#f0f6f1;border-radius:50%;width:28px;height:28px;display:grid;place-items:center;flex-shrink:0;font-size:11px}.operator-flow li:not(:last-child):before{content:'';position:absolute;left:14px;top:31px;bottom:-17px;width:1px;background:#d8e4db}dl{display:flex;flex-wrap:wrap;gap:5px 10px;margin:7px 0;font-size:12px}dt{color:#829084}dd{margin:0 12px 0 0}.adaptation{background:#eff5f0;border-radius:8px;padding:13px;display:flex;flex-wrap:wrap;gap:12px}.recipe-detail ul{padding-left:18px}.recipe-detail li{margin-bottom:9px;overflow-wrap:anywhere}.recipe-detail li span{display:block;margin-top:4px}a{color:#367653;text-decoration:none}a:hover{text-decoration:underline}p small{display:block;margin-top:7px}.contract-list{max-height:65vh;overflow:auto;padding-right:8px}.contract-list article{border:1px solid #e1e9e3;padding:18px;border-radius:9px;margin:12px 0}.contract-list header{display:flex;justify-content:space-between;align-items:center;gap:15px}.contract-list h3{font-size:14px}.pill{font-size:10px;background:#eff4ef;color:#738477;padding:4px 8px;border-radius:20px;white-space:nowrap}.pill.hard{color:#6c653f;background:#f5f2e8}.domains{display:grid;grid-template-columns:minmax(90px,auto) 1fr;gap:12px;margin-top:18px}.domains small{display:block;color:#819085;margin-top:5px}.empty{padding:40px;text-align:center;color:#819085}@media(max-width:850px){.method-layout{grid-template-columns:1fr}.method-layout aside{border-right:0;border-bottom:1px solid #e0e8e2}.method-layout nav{max-height:150px;grid-template-columns:repeat(2,minmax(0,1fr))}.recipe-detail{padding:18px}}
</style>
